from solution import is_palindrome


def test_palindrome():
    assert is_palindrome("A man, a plan, a canal: Panama") is True
    assert is_palindrome("race a car") is False
    assert is_palindrome("") is True
    assert is_palindrome("No 'x' in Nixon") is True

from solution import word_count


def test_w():
    assert word_count('The cat, the hat!') == {'the': 2, 'cat': 1, 'hat': 1}
    assert word_count('') == {}

from solution import top_k_frequent


def test_t():
    assert top_k_frequent([1, 1, 1, 2, 2, 3], 2) == [1, 2]
    assert top_k_frequent([5, 5, 3, 3], 2) == [3, 5]
    assert top_k_frequent([9], 1) == [9]

from solution import all_subsets


def test_s():
    got = {tuple(sorted(x)) for x in all_subsets([1, 2])}
    assert got == {(), (1,), (2,), (1, 2)}
    assert all_subsets([]) == [[]]
